import select
import logging

from six.moves.socketserver import BaseRequestHandler


class ForwardHandlerFactory(object):
    """
    Class generates new ForwardHandler object for each call.

    .. code-block:: python

        handlers_factory = ForwardHandlerFactory('1.1.1.1', 2222, ssh_client.get_transport())
        new_handler = handlers_factory(request, client_address, server)
    """
    def __init__(self, remote_ip, remote_port, ssh_transport, **kwargs):
        """
        :param string      remote_ip:      Destination IP Address for SSH direct channel (IP address of not directly
                                           reachable host).
        :param integer     remote_port:    Destination port for SSH direct channel (Port of not directly reachable
                                           service).
        :param Transport   ssh_transport:  Transport of connect SSH client which is required
                                           to create SSH channel to host specified by remote_ip and remote_port.
        """
        self.remote_ip = remote_ip
        self.remote_port = remote_port
        self._ssh_transport = ssh_transport

    def __call__(self, *args, **kwargs):
        return ForwardHandler(self.remote_ip, self.remote_port, self._ssh_transport, *args, **kwargs)


class ForwardHandler(BaseRequestHandler):
    """
    This class is instantiated for forwarding data from ssh transport channel to destination target.
    SSH transport channel is established between local and remote machine.

    :warning: Please use ForwardHandlerFactory with TCPServer/ThreadingTCPServer
              because server expects new ForwardHandler for each request.

    .. code-block:: python

        ForwardHandler('1.1.1.1', 2222, ssh_client.get_transport(), request, client_address, server)
    """
    def __init__(self, remote_ip, remote_port, ssh_transport, *args, **kwargs):
        """
        :param string      remote_ip:      Destination IP Address for SSH direct channel (IP address of not directly
                                           reachable host).
        :param integer     remote_port:    Destination port for SSH direct channel (Port of not directly reachable
                                           service).
        :param Transport   ssh_transport:  Transport of connect SSH client which is required
                                           to create SSH channel to host specified by remote_ip and remote_port.
        :param Logger      logger:         Logger object to be used for logging ForwardHandler status.
        """

        self._remote_ip = remote_ip
        self._remote_port = remote_port
        self._ssh_transport = ssh_transport
        self._log = logging.getLogger(self.__class__.__name__)
        BaseRequestHandler.__init__(self, *args, **kwargs)

    def handle(self):
        """
        Handles requests from TCPServer and forwards it between TCPServer and remote host connect via SSH direct channel
        """

        try:
            request_peername = self.request.getpeername()
            chan = self._ssh_transport.open_channel('direct-tcpip', (self._remote_ip, self._remote_port),
                                                    request_peername)
        except Exception as e:
            self._log.debug("Incoming request to ({}:{}) failed because of:\n{}".format(self._remote_ip,
                                                                                        self._remote_port, e))
            return False

        if chan is None:
            self._log.debug("Incoming request to ({}:{}) was rejected by the SSH server".format(self._remote_ip,
                                                                                                self._remote_port))
            return False

        self._log.debug("Connected! Tunnel open {} -> {} -> {}:{}".format(request_peername, chan.getpeername(),
                                                                          self._remote_ip, self._remote_port))
        self._forward_data_via_connected_channel(chan)
        self._close_connections(chan)

    def _forward_data_via_connected_channel(self, chan):
        while True:
            request_data_ready, chan_data_ready = self._check_if_data_is_ready(chan)
            if request_data_ready:
                if not self._forward_data(self.request, chan):
                    break
            if chan_data_ready:
                if not self._forward_data(chan, self.request):
                    break

    def _check_if_data_is_ready(self, chan):
        r, w, x = select.select([self.request, chan], [], [], 1)
        return self.request in r, chan in r

    def _forward_data(self, source, destination):
        try:
            data = source.recv(1024)
            if len(data) == 0:
                return False
            destination.send(data)
            return True
        except Exception as e:
            self._log.debug("Connection error appears: \n{}".format(e))
            return False

    def _close_connections(self, chan):
        chan.close()
        self.request.close()
        self._log.debug("Tunnel to {}:{} closed".format(self._remote_ip, self._remote_port))
